package com.dskmusic.lokate.data.offline

import java.util.Locale

/** Recuadro que cubre una zona. */
data class OfflineBounds(
    val south: Double,
    val west: Double,
    val north: Double,
    val east: Double,
) {
    fun contains(lat: Double, lng: Double): Boolean = lat in south..north && lng in west..east
}

/**
 * Una zona descargable del catálogo de Mapsforge.
 *
 * [approxBytes] es lo que pesaba el archivo al generar esta lista: sirve para enseñar algo en la
 * lista sin pedir nada a la red. El tamaño real se consulta al servidor justo antes de confirmar
 * la descarga (los mapas se regeneran cada pocas semanas y van creciendo).
 */
data class OfflineRegion(
    /** También el nombre del archivo local, sin extensión. */
    val id: String,
    val name: String,
    /** De dónde cuelga en el catálogo oficial: "Europe", "Europe · Germany"... */
    val group: String,
    /** Ruta dentro de [com.dskmusic.lokate.util.Constants.MAPSFORGE_BASE_URL], sin ".map". */
    val path: String,
    val approxBytes: Long,
    /** Código ISO cuando el archivo es un país entero: así el nombre sale en el idioma del móvil
     * en vez de en inglés, que es como los nombra el catálogo. */
    val countryCode: String? = null,
    /** Solo en las zonas escritas a mano, para poder sugerir "tu zona" antes de descargar nada.
     * Lo que cubre un mapa ya descargado se lee del propio archivo (ver [OfflineMaps.covers]). */
    val bounds: OfflineBounds? = null,
) {
    fun displayName(): String = countryCode
        ?.let { Locale("", it).getDisplayCountry(Locale.getDefault()) }
        ?.takeIf { it.isNotBlank() && !it.equals(countryCode, ignoreCase = true) }
        ?: name
}

