/** La zona más pequeña que cubre esa posición, para ofrecerle al usuario la suya. Solo mira las
 * que tienen recuadro (las de España): el catálogo oficial no publica los límites. */
fun suggestedRegion(lat: Double, lng: Double): OfflineRegion? =
    OfflineMapCatalog.firstOrNull { it.bounds?.contains(lat, lng) == true }

fun regionById(id: String): OfflineRegion? = OfflineMapCatalog.firstOrNull { it.id == id }
